//==================================================================================
// This is an autogenerated file. DO NOT EDIT.
// Top Parser module connecting all the modules
// Module: {{ module }}
//==================================================================================
module {{ module }} (
    input  logic    clk,
    input  logic    rst,
    input  logic [{{ top_in_width - 1 }}:0] data_in,
    input  logic    data_in_sop,
    input  logic    data_in_eop,
    input  logic    data_in_valid,
    input  logic    field_ready_in,
    output logic    data_in_ready,
    output logic    field_valid_out,
    {% for field in fields -%}
    output logic [{{ field.width - 1 }}:0] {{ field.name }}_out{% if not loop.last -%},{% endif %}
    {% endfor -%}
);

logic [{{ path_id_width }}-1:0] path_id_hex_to_rtl_top;
logic hex_to_rtl_top_output_valid;
(* DONT_TOUCH = "TRUE" *) logic field_valid_r;

// ---- Input AXI skid buffer ----
// parser_top owns the skid, so the wrapped hex_to_rtl_top is built with
// SKID_EN=0. All downstream consumers use the post-skid stream (core_*).
logic [{{ top_in_width - 1 }}:0] core_data_in;
logic core_data_in_sop, core_data_in_eop, core_data_in_valid;
logic comp_lookup_ready;   // hex_to_rtl_top's data_in_ready (downstream ready)

axi_skid #(.WIDTH({{ top_in_width }})) u_input_skid (
    .clk            (clk),
    .rst            (rst),
    .data_in        (data_in),
    .data_in_sop    (data_in_sop),
    .data_in_eop    (data_in_eop),
    .data_in_valid  (data_in_valid),
    .data_in_ready  (data_in_ready),
    .data_out       (core_data_in),
    .data_out_sop   (core_data_in_sop),
    .data_out_eop   (core_data_in_eop),
    .data_out_valid (core_data_in_valid),
    .data_out_ready (comp_lookup_ready)
);

//Hex to rtl top instance (skid disabled — owned by parser_top)
hex_to_rtl_top #(.SKID_EN(0))
  u_comp_lookup (
    .clk              (clk),
    .rst              (rst),
    .data_in          (core_data_in),
    .data_in_sop      (core_data_in_sop),
    .data_in_eop      (core_data_in_eop),
    .data_in_valid    (core_data_in_valid),
    .path_id_out_ready(field_ready_in),
    .path_id_out      (path_id_hex_to_rtl_top),
    .path_id_out_valid(hex_to_rtl_top_output_valid),
    .data_in_ready    (comp_lookup_ready)
);

// Flit-counter: resets to 0 on SOP, increments each valid cycle, saturates at num_pipes-1
{%- if num_pipes > 1 %}
(* DONT_TOUCH = "TRUE" *) logic [$clog2({{ num_pipes }})-1:0] flit_counter;

always_ff @(posedge clk or posedge rst) begin
    if (rst) begin
        flit_counter <= '0;
    end else if (core_data_in_valid) begin
        if (core_data_in_sop)
            flit_counter <= '0;
        else if (flit_counter < {{ num_pipes - 1 }})
            flit_counter <= flit_counter + 1'b1;
    end
end
{%- endif %}

// Per-flit latch registers — capture data_i for each flit as it arrives
{%- for i in range(num_pipes) %}
(* DONT_TOUCH = "TRUE" *) logic [{{ top_in_width - 1 }}:0] data_i_latched_{{ i }};
{%- endfor %}

{%- for i in range(num_pipes) %}
{%- if i == 0 %}
always_ff @(posedge clk) begin
    if (core_data_in_valid && core_data_in_sop)
        data_i_latched_0 <= core_data_in;
end
{%- else %}
always_ff @(posedge clk) begin
    if (core_data_in_valid && (flit_counter == {{ i - 1 }}))
        data_i_latched_{{ i }} <= core_data_in;
end
{%- endif %}
{%- endfor %}

// Concatenate all latched flits and register once to align with path_id_out
logic [{{ top_in_width * num_pipes }}-1:0] data_accum;
(* DONT_TOUCH = "TRUE" *) logic [{{ top_in_width * num_pipes }}-1:0] data_accum_r;

assign data_accum = {
    {%- for i in range(num_pipes) %}
    data_i_latched_{{ i }}{% if i < num_pipes - 1 %},{% endif %}
    {%- endfor %}
};

always_ff @(posedge clk) begin
    data_accum_r <= data_accum;
end

// field_valid_out is one cycle after path_id_out_valid to align with registered field outputs
always_ff @(posedge clk or posedge rst) begin
    if (rst)
        field_valid_r <= '0;
    else
        field_valid_r <= hex_to_rtl_top_output_valid;
end
assign field_valid_out = field_valid_r;

//Output declarations
{% for field in fields %}
logic [{{ field.width - 1 }}:0] {{ field.name }}_out_t;
{%- endfor %}


//Extractor module instance
mask_extractor
  u_mask_extractor (
    .data_in        (data_accum_r),
    .path_id        (path_id_hex_to_rtl_top),
{%- for field in fields %}
    .{{ field.name }}_out       ({{ field.name }}_out_t){% if not loop.last -%},{% endif %}
{%- endfor %}
);

always_ff @(posedge clk) begin
{%- for field in fields %}
    {{ field.name }}_out <= {{ field.name }}_out_t;
{%- endfor %}
end

endmodule: {{ module }}
